-- Generated by model/lib/sql/generate.mjs. Loads IMPORT FX Rate from cells/IMPORT FX Rate.csv in the folder of input cells. Two rows for one cell add up.
-- @csv cells/IMPORT FX Rate.csv
INSERT INTO "IMPORT FX Rate" SELECT coalesce(k0."Currency", fpabench_error('cells name a member Currency does not have: ' || c."Currency")), coalesce(k1."Years", fpabench_error('cells name a member Years does not have: ' || c."Years")), coalesce(k2."Months", fpabench_error('cells name a member Months does not have: ' || c."Months")), sum(c.value::DOUBLE PRECISION)
FROM csv c LEFT JOIN "dim Currency" k0 ON k0.name = c."Currency" LEFT JOIN "dim Years" k1 ON k1.name = c."Years" LEFT JOIN "dim Months" k2 ON k2.name = c."Months"
GROUP BY 1, 2, 3
ON CONFLICT ("Currency", "Years", "Months") DO UPDATE SET v = EXCLUDED.v;
ANALYZE "IMPORT FX Rate";
